export const AREA_PERIMETER_ACTIVITIES = [
// PHASE A — CONCRETE (1-20): benda fisik nyata — berjalan mengelilingi tepi taman (keliling), menutupi lantai dengan ubin (luas), menghitung persegi satuan nyata
{"n":1,"type":"mcq","micro":"Keliling sebagai berjalan mengelilingi tepi","q":"Jika kamu berjalan sepenuhnya mengelilingi tepi luar taman persegi panjang, apa yang kamu ukur?","options":["Tinggi taman itu","Keliling taman itu","Luas taman itu"],"answer":1,"explain":"Berjalan sepenuhnya mengelilingi tepi luar sebuah bentuk mengukur kelilingnya, total jarak di sekelilingnya.","hint":"Apakah berjalan mengelilingi TEPI LUAR mengukur jarak sekeliling suatu bentuk, atau ruang yang ditutupinya?"},
{"n":2,"type":"mcq","micro":"Luas sebagai menutupi permukaan","q":"Jika kamu menutupi lantai persegi panjang sepenuhnya dengan ubin persegi (tanpa celah atau tumpang tindih), apa yang kamu ukur dengan menghitung ubinnya?","options":["Keliling lantai itu","Berat lantai itu","Luas lantai itu"],"answer":2,"explain":"Menghitung ubin persegi yang dibutuhkan untuk sepenuhnya menutupi suatu permukaan mengukur luasnya.","hint":"Apakah menghitung ubin yang MENUTUPI seluruh permukaan mengukur ruang di dalam suatu bentuk, atau jarak di sekelilingnya?"},
{"n":3,"type":"tf","micro":"Keliling vs luas adalah pengukuran yang berbeda","q":"Benar atau Salah: Keliling (jarak di sekeliling suatu bentuk) dan luas (ruang yang ditutupi suatu bentuk) mengukur dua hal yang sama sekali berbeda tentang bentuk yang sama.","answer":true,"explain":"Keliling mengukur jarak di sekeliling tepi luar, sementara luas mengukur ruang yang ditutupi di dalam — dua pengukuran yang benar-benar berbeda.","hint":"Apakah mengukur jarak DI SEKELILING suatu bentuk memberimu informasi yang sama dengan mengukur ruang DI DALAMNYA?"},
{"n":4,"type":"mcq","micro":"Keliling konkret (pagar)","q":"Seorang petani ingin membangun pagar sepenuhnya mengelilingi ladang persegi panjang. Pengukuran apa yang perlu diketahui petani itu untuk membeli jumlah pagar yang tepat?","options":["Keliling ladang itu","Luas ladang itu","Volume ladang itu"],"answer":0,"explain":"Pagar dipasang di sekeliling TEPI LUAR ladang, jadi petani itu butuh kelilingnya.","hint":"Apakah pagar dipasang di sekeliling tepi luar, atau menutupi ruang di dalamnya?"},
{"n":5,"type":"mcq","micro":"Luas konkret (karpet)","q":"Sebuah keluarga ingin membeli karpet untuk sepenuhnya menutupi lantai ruang tamu persegi panjang mereka. Pengukuran apa yang perlu mereka ketahui?","options":["Keliling lantai itu","Luas lantai itu","Tinggi langit-langit"],"answer":1,"explain":"Karpet menutupi RUANG DI DALAM lantai, jadi keluarga itu butuh luasnya.","hint":"Apakah karpet menutupi tepi luar sebuah ruangan, atau seluruh ruang lantai di dalamnya?"},
{"n":6,"type":"mcq","micro":"Keliling konkret (menghitung langkah mengelilingi bentuk)","q":"Kamu berjalan mengelilingi taman bermain persegi panjang: 10 langkah di satu sisi, 6 langkah di sisi berikutnya, 10 langkah di sisi ketiga, dan 6 langkah di sisi terakhir. Berapa total langkah yang kamu jalani?","options":["60 langkah","16 langkah","32 langkah"],"answer":2,"explain":"10+6+10+6=32 total langkah, menjumlahkan setiap sisi yang kamu jalani.","hint":"Jumlahkan langkah dari keempat sisi persegi panjang yang kamu kelilingi."},
{"n":7,"type":"tf","micro":"Luas diukur dalam satuan persegi","q":"Benar atau Salah: Luas diukur menggunakan satuan persegi (seperti meter persegi atau sentimeter persegi), karena itu menggambarkan RUANG datar, bukan hanya panjang.","answer":true,"explain":"Karena luas menggambarkan ruang 2D (bukan hanya satu panjang), itu diukur dalam satuan persegi, seperti m² atau cm².","hint":"Apakah luas menggambarkan hanya satu jarak/panjang, atau ruang datar dua dimensi?"},
{"n":8,"type":"mcq","micro":"Perbandingan konkret (keliling)","q":"Taman A memiliki keliling yang bisa kamu jalani mengelilinginya dalam 40 langkah. Taman B memiliki keliling yang bisa kamu jalani mengelilinginya dalam 60 langkah. Taman mana yang kelilingnya lebih besar?","options":["Taman B","Taman A","Keduanya sama"],"answer":0,"explain":"60 langkah lebih dari 40 langkah, jadi Taman B memiliki keliling yang lebih besar (jarak yang lebih panjang di sekelilingnya).","hint":"Taman mana yang membutuhkan LEBIH BANYAK langkah untuk mengelilinginya sepenuhnya?"},
{"n":9,"type":"mcq","micro":"Soal cerita konkret (luas, persegi satuan)","q":"Sebuah petak taman persegi panjang ditutupi tepat oleh 24 ubin persegi identik, tanpa celah atau tumpang tindih. Berapa luas petak taman itu, dalam ubin persegi?","options":["12 ubin persegi","24 ubin persegi","24 ubin di sekeliling tepi"],"answer":1,"explain":"Karena 24 ubin sepenuhnya menutupi petak itu tanpa celah atau tumpang tindih, luasnya adalah 24 satuan-ubin persegi.","hint":"Berapa ubin persegi yang dibutuhkan untuk sepenuhnya menutupi seluruh petak taman itu?"},
{"n":10,"type":"mcq","micro":"Keliling konkret pada penggaris nyata","q":"Kamu mengukur keempat sisi bingkai foto persegi panjang dengan penggaris: 20 cm, 15 cm, 20 cm, 15 cm. Berapa total kelilingnya?","options":["35 cm","300 cm","70 cm"],"answer":2,"explain":"20+15+20+15=70 cm total keliling.","hint":"Jumlahkan panjang keempat sisi yang kamu ukur."},
{"n":11,"type":"mcq","micro":"Identifikasi luas konkret","q":"Mana dari pertanyaan ini yang menanyakan tentang LUAS, bukan keliling?","options":["Berapa banyak cat yang dibutuhkan untuk sepenuhnya menutupi dinding ini?","Berapa banyak pita yang dibutuhkan untuk mengelilingi tepi tutup kotak ini?","Berapa banyak pagar yang dibutuhkan untuk mengelilingi halaman ini?"],"answer":0,"explain":"Menutupi dinding sepenuhnya dengan cat adalah tentang RUANG yang ditutupi (luas); pagar dan pita-tepi adalah tentang jarak DI SEKELILING suatu bentuk (keliling).","hint":"Apakah 'menutupi dinding sepenuhnya' menggambarkan ruang di dalam, atau hanya tepi luar?"},
{"n":12,"type":"tf","micro":"Keliling sama tidak berarti luas sama","q":"Benar atau Salah: Dua persegi panjang berbeda bisa memiliki keliling yang persis sama, tetapi tetap menutupi jumlah ruang yang berbeda (luas berbeda).","answer":true,"explain":"Persegi panjang yang panjang dan tipis serta yang lebih mendekati persegi bisa memiliki keliling identik sambil menutupi jumlah luas yang sangat berbeda.","hint":"Bisakah persegi panjang yang sangat panjang dan tipis serta persegi panjang yang lebih berbentuk persegi memiliki total jarak sekeliling yang sama, tetapi jumlah ruang yang ditutupi berbeda?"},
{"n":13,"type":"mcq","micro":"Keliling konkret (lapangan olahraga)","q":"Sebuah lapangan olahraga persegi panjang panjangnya 100 m dan lebarnya 50 m. Jika kamu berlari sekali sepenuhnya mengelilingi tepi luarnya, seberapa jauh kamu berlari?","options":["300 m","5.000 m","150 m"],"answer":0,"explain":"Keliling = 100+50+100+50=300 m.","hint":"Jumlahkan keempat sisi: panjang, lebar, panjang, lebar."},
{"n":14,"type":"mcq","micro":"Soal cerita konkret (membandingkan luas dengan menghitung persegi)","q":"Ruangan A ditutupi oleh 18 ubin persegi identik. Ruangan B ditutupi oleh 24 ubin persegi identik (ubin berukuran sama). Ruangan mana yang luas lantainya lebih besar?","options":["Ruangan A","Ruangan B","Luasnya sama"],"answer":1,"explain":"24 ubin menutupi lebih banyak ruang daripada 18 ubin (dengan asumsi ubinnya berukuran sama), jadi Ruangan B memiliki luas lebih besar.","hint":"Ruangan mana yang butuh LEBIH BANYAK ubin persegi identik untuk sepenuhnya menutupi lantainya?"},
{"n":15,"type":"mcq","micro":"Keliling konkret pada denah taman nyata","q":"Sebuah petak taman memiliki 4 sisi berukuran 8 m, 5 m, 8 m, dan 5 m. Jika kamu menanam bunga pembatas setiap 1 meter di sepanjang seluruh tepi luarnya, berapa bunga pembatas yang kamu butuhkan?","options":["13 bunga","40 bunga","26 bunga"],"answer":2,"explain":"Keliling = 8+5+8+5=26 m, dan menanam satu bunga setiap 1 meter di sepanjang seluruh tepi 26 m itu membutuhkan 26 bunga.","hint":"Cari dulu total kelilingnya, karena itu memberitahumu total jarak yang perlu ditutupi bunga-bunga itu."},
{"n":16,"type":"mcq","micro":"Luas konkret pada denah taman nyata","q":"Petak taman yang sama (8 m kali 5 m) perlu sepenuhnya ditutupi rumput gulung, dijual dalam potongan 1-meter-persegi. Berapa potongan rumput gulung yang dibutuhkan?","options":["13 potongan","26 potongan","40 potongan"],"answer":2,"explain":"Menutupi SELURUH ruang di dalam (luas) membutuhkan 8×5=40 potongan rumput gulung satu-meter-persegi.","hint":"Ini menanyakan tentang menutupi SELURUH PERMUKAAN DI DALAM, bukan hanya tepinya — pengukuran mana itu?"},
{"n":17,"type":"tf","micro":"Keliling menggunakan satuan biasa, bukan satuan persegi","q":"Benar atau Salah: Keliling diukur menggunakan satuan panjang biasa (seperti meter atau sentimeter), bukan satuan persegi, karena itu menggambarkan jarak, bukan ruang yang ditutupi.","answer":true,"explain":"Karena keliling hanyalah total jarak (sebuah panjang), itu diukur dalam satuan biasa seperti m atau cm, bukan satuan persegi.","hint":"Apakah keliling menggambarkan ruang datar yang ditutupi, atau sekadar total jarak di sekeliling tepi?"},
{"n":18,"type":"mcq","micro":"Soal cerita konkret (tepi kolam renang nyata)","q":"Sebuah kolam renang persegi panjang membutuhkan tali keselamatan yang dipasang sepenuhnya mengelilingi tepinya. Pengukuran apa yang menentukan berapa banyak tali yang dibutuhkan?","options":["Luas permukaan air kolam itu","Keliling kolam itu","Kedalaman kolam itu"],"answer":1,"explain":"Tali yang dipasang di sekeliling TEPI LUAR kolam membutuhkan pengetahuan tentang kelilingnya.","hint":"Apakah tali yang dipasang 'di sekeliling tepi' mengukur jarak di sekeliling, atau ruang permukaan di dalamnya?"},
{"n":19,"type":"mcq","micro":"Soal cerita konkret (penutup kolam renang nyata)","q":"Kolam renang yang sama membutuhkan penutup yang sepenuhnya menutupi permukaan airnya saat tidak digunakan. Pengukuran apa yang menentukan ukuran penutup yang dibutuhkan?","options":["Luas permukaan air kolam itu","Keliling kolam itu","Kedalaman kolam itu"],"answer":0,"explain":"Penutup yang sepenuhnya menutupi permukaan air membutuhkan pengetahuan tentang luasnya.","hint":"Apakah penutup kolam perlu cocok dengan jarak di sekeliling tepi, atau seluruh permukaan datarnya?"},
{"n":20,"type":"mcq","micro":"Memeriksa klaim pengukuran konkret","q":"Seseorang berkata keliling sebuah ruangan persegi panjang adalah '20 meter persegi.' Apa yang salah dari pernyataan ini?","options":["Keliling seharusnya diukur dalam satuan biasa (seperti meter), bukan satuan persegi — 'meter persegi' sebenarnya adalah satuan untuk luas, bukan keliling","Tidak ada yang salah; ini cara yang sepenuhnya benar untuk menggambarkan keliling","Ruangan tidak bisa memiliki keliling sama sekali"],"answer":0,"explain":"'Meter persegi' adalah satuan yang benar untuk LUAS, bukan keliling — keliling seharusnya diberikan dalam satuan panjang biasa seperti meter.","hint":"Apakah 'meter persegi' menggambarkan jarak di sekeliling tepi, atau ruang datar yang ditutupi?"},

// PHASE B — PICTORIAL (21-40): diagram kisi, menghitung persegi satuan dalam gambar, diagram persegi panjang berlabel untuk keliling/luas
{"n":21,"type":"mcq","micro":"Membaca luas dari gambar kisi","q":"Sebuah gambar menunjukkan persegi panjang digambar pada kisi, sepenuhnya menutupi 15 persegi satuan. Berapa luas persegi panjang ini?","options":["4 satuan (menghitung sisi)","15 satuan","15 satuan persegi"],"answer":2,"explain":"Menghitung persegi satuan yang sepenuhnya ditutupi persegi panjang itu langsung memberikan luasnya: 15 satuan persegi.","hint":"Berapa persegi satuan kecil yang ditutupi persegi panjang itu dalam gambar?"},
{"n":22,"type":"mcq","micro":"Membaca keliling dari diagram berlabel","q":"Sebuah diagram menunjukkan persegi panjang berlabel panjang 7 cm dan lebar 4 cm pada setiap sisi yang relevan. Berapa kelilingnya?","options":["11 cm","22 cm","28 cm"],"answer":1,"explain":"Keliling=7+4+7+4=22 cm (menjumlahkan keempat sisi).","hint":"Jumlahkan panjang keempat sisi persegi panjang yang ditunjukkan dalam diagram itu."},
{"n":23,"type":"mcq","micro":"Membandingkan luas bergambar (menghitung kisi)","q":"Bentuk A pada kisi menutupi 12 persegi satuan. Bentuk B pada kisi yang sama menutupi 18 persegi satuan. Bentuk mana yang luasnya lebih besar?","options":["Keduanya sama","Bentuk B","Bentuk A"],"answer":1,"explain":"18 persegi satuan lebih dari 12, jadi Bentuk B memiliki luas lebih besar.","hint":"Hitung dan bandingkan langsung jumlah persegi satuan yang ditutupi setiap bentuk."},
{"n":24,"type":"mcq","micro":"Membaca diagram kisi (baris dan kolom)","q":"Sebuah persegi panjang pada kisi lebarnya 6 persegi satuan dan tingginya 3 persegi satuan, disusun rapi dalam baris dan kolom. Berapa total persegi satuan yang ditutupinya?","options":["18 persegi satuan","6 persegi satuan","9 persegi satuan"],"answer":0,"explain":"6 kolom × 3 baris = 18 total persegi satuan (ini adalah dasar visual untuk rumus luas panjang × lebar).","hint":"Berapa persegi satuan di SETIAP dari 3 baris itu, dan berapa banyak baris totalnya?"},
{"n":25,"type":"order","micro":"Mengurutkan (menemukan keliling dari diagram berlabel)","q":"Urutkan langkah-langkah berikut untuk menemukan keliling persegi panjang berlabel panjang 9 cm dan lebar 5 cm.","items":["Jumlahkan keempat sisi bersama: 9+5+9+5=28 cm","Identifikasi kedua panjang sisi berbeda yang ditunjukkan pada diagram (9 cm dan 5 cm)","Sadari bahwa persegi panjang memiliki dua pasang sisi sama yang berlawanan"],"answer":[1,2,0],"explain":"Pertama identifikasi panjang sisi yang diberikan, lalu sadari sifat sisi-sama-berlawanan persegi panjang, lalu jumlahkan keempat sisi bersama.","hint":"Bisakah kamu menjumlahkan keempat sisi sebelum kamu mengidentifikasi panjang yang diberikan dan menyadari sisi mana yang berulang?"},
{"n":26,"type":"mcq","micro":"Diagram kisi (panjang sisi yang hilang dari luas)","q":"Sebuah persegi panjang pada kisi menutupi total 20 persegi satuan dan lebarnya 5 persegi satuan. Setinggi berapa persegi satuan bentuk itu?","options":["20 persegi satuan","15 persegi satuan","4 persegi satuan"],"answer":2,"explain":"20÷5=4, karena lebar × tinggi = total luas, jadi tinggi=20÷5=4.","hint":"Bagi total luas dengan lebar yang diketahui untuk menemukan tinggi yang hilang."},
{"n":27,"type":"mcq","micro":"Membaca diagram bentuk tidak beraturan (luas gabungan)","q":"Sebuah gambar menunjukkan ruangan berbentuk L yang terbuat dari dua persegi panjang: satu menutupi 12 persegi satuan dan yang lain menutupi 8 persegi satuan, tanpa tumpang tindih. Berapa total luas ruangan berbentuk L itu?","options":["96 persegi satuan","20 persegi satuan","4 persegi satuan"],"answer":1,"explain":"12+8=20 total persegi satuan, menjumlahkan kedua bagian persegi panjang yang tidak tumpang tindih itu bersama.","hint":"Jumlahkan luas kedua bagian persegi panjang terpisah itu bersama, karena mereka tidak tumpang tindih."},
{"n":28,"type":"tf","micro":"Gambar kisi menunjukkan luas secara langsung dengan menghitung","q":"Benar atau Salah: Pada diagram kisi, kamu bisa menemukan luas suatu bentuk cukup dengan menghitung berapa persegi satuan yang sepenuhnya ditutupinya, tanpa membutuhkan rumus apa pun.","answer":true,"explain":"Menghitung langsung persegi satuan pada kisi adalah cara yang valid dan bebas-rumus untuk menemukan luas — ini persis konsep yang menjadi dasar rumus panjang×lebar.","hint":"Bisakah menghitung persegi yang diarsir/ditutupi pada kisi memberimu luasnya, bahkan tanpa menggunakan rumus perkalian?"},
{"n":29,"type":"mcq","micro":"Membaca diagram (keliling bentuk tidak beraturan)","q":"Sebuah gambar menunjukkan taman berbentuk L dengan semua tepi luarnya berlabel: 6 m, 4 m, 3 m, 2 m, 3 m, 2 m (sepenuhnya mengelilingi). Berapa total kelilingnya?","options":["24 m","18 m","20 m"],"answer":2,"explain":"6+4+3+2+3+2=20 m, menjumlahkan setiap tepi luar berlabel sepenuhnya mengelilingi bentuk itu.","hint":"Jumlahkan setiap panjang tepi berlabel tunggal yang ditunjukkan sepenuhnya mengelilingi luar bentuk itu."},
{"n":30,"type":"mcq","micro":"Model batang/diagram membandingkan luas dan keliling","q":"Sebuah diagram menunjukkan dua persegi panjang berbeda yang memiliki keliling SAMA (masing-masing 20 cm) tetapi bentuk berbeda: satu 8 cm kali 2 cm, yang lain 5 cm kali 5 cm. Persegi panjang mana yang luasnya lebih besar?","options":["Persegi panjang 5 cm kali 5 cm","Luasnya sama","Persegi panjang 8 cm kali 2 cm"],"answer":0,"explain":"8×2=16 cm persegi, sementara 5×5=25 cm persegi — persegi panjang yang lebih 'berbentuk persegi' memiliki luas yang lebih besar, meskipun kelilingnya sama.","hint":"Hitung luas setiap persegi panjang (panjang×lebar) dan bandingkan secara langsung."},
{"n":31,"type":"mcq","micro":"Membaca diagram (kasus khusus persegi)","q":"Sebuah diagram menunjukkan persegi dengan setiap sisi berlabel 6 cm. Berapa keliling persegi itu?","options":["12 cm","24 cm","36 cm"],"answer":1,"explain":"Sebuah persegi memiliki 4 sisi sama, jadi keliling=6×4=24 cm.","hint":"Sebuah persegi memiliki 4 sisi sama — kalikan panjang satu sisi dengan 4."},
{"n":32,"type":"classify","micro":"Menanyakan tentang luas, atau menanyakan tentang keliling?","q":"Kelompokkan setiap pertanyaan dunia nyata bergambar berdasarkan apakah sebenarnya menanyakan tentang LUAS atau KELILING.","items":["Berapa banyak wallpaper yang menutupi dinding ini?","Berapa banyak tali yang membungkus kotak ini?","Berapa banyak biji rumput yang menutupi halaman ini?","Berapa banyak pita yang menghias tepi taplak meja ini?"],"groups":["Luas","Keliling"],"answer":{"Luas":["Berapa banyak wallpaper yang menutupi dinding ini?","Berapa banyak biji rumput yang menutupi halaman ini?"],"Keliling":["Berapa banyak tali yang membungkus kotak ini?","Berapa banyak pita yang menghias tepi taplak meja ini?"]},"explain":"Wallpaper dan biji rumput menutupi seluruh permukaan (luas); tali dan pita mengelilingi tepi (keliling).",hint:"Apakah pertanyaan itu menggambarkan menutupi seluruh permukaan, atau mengelilingi tepi?"},
{"n":33,"type":"mcq","micro":"Membaca diagram (luas persegi)","q":"Sebuah diagram menunjukkan persegi dengan setiap sisi berlabel 6 cm. Berapa luas persegi itu?","options":["36 cm persegi","24 cm persegi","12 cm persegi"],"answer":0,"explain":"Luas persegi = sisi × sisi = 6×6=36 cm persegi.",hint:"Untuk persegi, luas adalah panjang satu sisi dikalikan dengan dirinya sendiri."},
{"n":34,"type":"mcq","micro":"Soal cerita diagram kisi (keliling gabungan)","q":"Sebuah gambar menunjukkan persegi panjang dengan sebuah lekukan persegi panjang lebih kecil dipotong dari satu sudutnya. Apakah memotong lekukan dari persegi panjang selalu mengubah kelilingnya dengan cara yang sama seperti mengubah luasnya?",options:["Tidak, memotong lekukan tidak pernah mempengaruhi keliling sama sekali","Ya, memotong lekukan selalu mengurangi baik luas maupun keliling dengan jumlah yang sama","Tidak — memotong lekukan selalu MENGURANGI luasnya, tetapi sebenarnya bisa MENAMBAH total kelilingnya (karena tepi baru ditambahkan di sekeliling lekukan itu)"],answer:2,explain:"Menghilangkan lekukan selalu mengurangi luas (lebih sedikit ruang yang ditutupi), tetapi sering menambahkan tepi baru, yang sebenarnya bisa meningkatkan total keliling — perbedaan yang mengejutkan tetapi penting.",hint:"Apakah memotong lekukan dari suatu bentuk menghilangkan panjang tepi apa pun, atau justru menambahkan tepi baru di sekeliling lekukan itu?"},
{"n":35,"type":"mcq","micro":"Membandingkan keliling bergambar (bentuk berbeda)","q":"Garis luar Bentuk A (persegi panjang panjang dan tipis) memiliki keliling 30 cm. Garis luar Bentuk B (persegi panjang lebih berbentuk persegi) juga memiliki keliling 30 cm. Haruskah luas mereka juga sama?",options:["Ya, keliling sama selalu berarti luas sama","Tidak, mereka bisa memiliki luas yang sangat berbeda bahkan dengan keliling yang sama","Tidak mungkin dua bentuk berbeda berbagi keliling yang sama"],answer:1,explain:"Seperti yang ditunjukkan sebelumnya, bentuk dengan keliling sama bisa memiliki luas yang sangat berbeda, tergantung pada proporsi sebenarnya.",hint:"Apakah memiliki total jarak sekeliling yang sama pada dua bentuk menjamin mereka menutupi jumlah ruang yang sama di dalamnya?"},
{"n":36,"type":"tf","micro":"Estimasi piktorial dengan luas","q":"Benar atau Salah: Sebuah gambar kisi yang menunjukkan bentuk menutupi hampir seluruh kisi mewakili luas yang jauh lebih besar daripada gambar yang menunjukkan bentuk yang hanya menutupi sudut kecil kisi berukuran sama.",answer:true,explain:"Sebuah bentuk yang menutupi hampir seluruh kisi memiliki luas yang jauh lebih besar daripada yang hanya menutupi sebagian kecil kisi yang sama.",hint:"Apakah menutupi lebih banyak dari kisi berukuran sama mewakili luas yang lebih besar atau lebih kecil?"},
{"n":37,"type":"mcq","micro":"Membaca diagram (persegi panjang dengan hanya dua sisi berlabel)","q":"Sebuah diagram persegi panjang hanya melabeli dua sisi berdekatan: 'panjang: 12 m' dan 'lebar: 7 m.' Mengapa tetap mungkin menemukan keliling lengkapnya hanya dari kedua label ini?",options:["Karena kamu tidak pernah bisa menemukan keliling hanya dengan dua sisi berlabel","Karena persegi panjang tidak pernah memiliki sisi berlawanan yang sama","Karena sisi berlawanan persegi panjang selalu sama, jadi kedua sisi lainnya otomatis juga 12 m dan 7 m"],answer:2,explain:"Sisi berlawanan persegi panjang selalu sama panjang, jadi mengetahui satu panjang dan satu lebar sudah cukup untuk menentukan keempat sisinya.",hint:"Pada persegi panjang, apakah kedua panjangnya selalu sama satu sama lain, dan kedua lebarnya selalu sama satu sama lain?"},
{"n":38,"type":"mcq","micro":"Menjembatani piktorial ke abstrak (pola rumus luas)","q":"Melihat beberapa persegi panjang kisi: persegi panjang 2×3 menutupi 6 persegi, 2×4 menutupi 8 persegi, 2×5 menutupi 10 persegi — pola apa yang menghubungkan kedua panjang sisi dengan total luas?",options:["Luas selalu sama dengan kedua panjang sisi dikalikan bersama (panjang × lebar)","Luas selalu sama dengan kedua panjang sisi dijumlahkan bersama","Tidak ada pola konsisten yang menghubungkan sisi dengan luas"],answer:0,explain:"Di setiap contoh, mengalikan kedua panjang sisi bersama (2×3=6, 2×4=8, 2×5=10) memberikan total luas yang tepat — ini adalah rumus panjang×lebar.",hint:"Coba kalikan kedua panjang sisi setiap persegi panjang bersama — apakah itu cocok dengan total hitungan persegi?"},
{"n":39,"type":"mcq","micro":"Soal cerita piktorial (luas bukaan bingkai foto)","q":"Bukaan dalam bingkai foto persegi panjang (tempat foto diletakkan) ditunjukkan pada kisi, menutupi 35 persegi satuan, disusun sebagai 7 lebar dan 5 tinggi. Apakah ini cocok dengan pola panjang×lebar?",options:["Tidak mungkin memeriksa ini tanpa benar-benar menghitung setiap persegi","Ya, 7×5=35, cocok tepat dengan hitungan kisi","Tidak, hitungan kisi dan perkaliannya tidak cocok"],answer:1,explain:"7×5=35, tepat cocok dengan jumlah persegi satuan yang dihitung pada kisi, mengonfirmasi rumus panjang×lebar berhasil.",hint:"Kalikan kedua dimensi yang diberikan (7 dan 5) dan bandingkan itu dengan total hitungan persegi (35)."},
{"n":40,"type":"mcq","micro":"Memilih strategi gambar untuk menemukan luas gabungan","q":"Untuk menemukan total luas ruangan berbentuk L yang ditunjukkan dalam diagram, apa pendekatan yang membantu?",options:["Tidak mungkin menemukan luas bentuk apa pun yang bukan persegi panjang sederhana","Cukup kalikan sisi terpanjang dengan sisi terpendek dari keseluruhan bentuk L","Pecah bentuk L itu menjadi dua persegi panjang terpisah, temukan luas setiap persegi panjang secara terpisah, lalu jumlahkan kedua luas itu bersama"],answer:2,explain:"Memecah bentuk tidak beraturan (gabungan) menjadi persegi panjang sederhana, menemukan setiap luas, lalu menjumlahkannya adalah strategi andal untuk bentuk gabungan.",hint:"Bisakah memecah bentuk L menjadi dua persegi panjang lebih sederhana membuatnya lebih mudah menemukan total luasnya?"},

// PHASE C — ABSTRACT BRIDGING (41-60): rumus keliling/luas untuk persegi panjang/persegi, bentuk gabungan, panjang sisi yang hilang, konversi satuan
{"n":41,"type":"mcq","micro":"Rumus keliling (persegi panjang)","q":"Menggunakan rumus, temukan keliling persegi panjang dengan panjang 9 cm dan lebar 4 cm.",options:["26 cm","13 cm","36 cm"],answer:0,explain:"Keliling=2×(panjang+lebar)=2×(9+4)=2×13=26 cm.",hint:"Jumlahkan panjang dan lebar bersama, lalu gandakan hasilnya."},
{"n":42,"type":"mcq","micro":"Rumus luas (persegi panjang)","q":"Menggunakan rumus, temukan luas persegi panjang dengan panjang 9 cm dan lebar 4 cm.",options:["36 cm persegi","13 cm persegi","26 cm persegi"],answer:0,explain:"Luas=panjang×lebar=9×4=36 cm persegi.",hint:"Kalikan panjang dengan lebar."},
{"n":43,"type":"mcq","micro":"Rumus keliling (persegi)","q":"Menggunakan rumus, temukan keliling persegi dengan panjang sisi 8 m.",options:["16 m","32 m","64 m"],answer:1,explain:"Keliling persegi=4×sisi=4×8=32 m.",hint:"Kalikan panjang sisi yang diberikan dengan 4."},
{"n":44,"type":"mcq","micro":"Rumus luas (persegi)","q":"Menggunakan rumus, temukan luas persegi dengan panjang sisi 8 m.",options:["32 m persegi","16 m persegi","64 m persegi"],answer:2,explain:"Luas persegi=sisi×sisi=8×8=64 m persegi.",hint:"Kalikan panjang sisi dengan dirinya sendiri."},
{"n":45,"type":"mcq","micro":"Menemukan sisi yang hilang dari keliling","q":"Sebuah persegi panjang memiliki keliling 30 cm dan panjang 9 cm. Berapa lebarnya?",options:["6 cm","4,5 cm","21 cm"],answer:0,explain:"Keliling=2×(panjang+lebar), jadi 30=2×(9+lebar), memberikan 15=9+lebar, jadi lebar=6 cm.",hint:"Bagi kelilingnya dengan 2 dulu untuk menemukan jumlah satu panjang dan satu lebar, lalu kurangkan panjang yang diketahui."},
{"n":46,"type":"mcq","micro":"Menemukan sisi yang hilang dari luas","q":"Sebuah persegi panjang memiliki luas 48 cm persegi dan lebar 6 cm. Berapa panjangnya?",options:["42 cm","8 cm","288 cm"],answer:1,explain:"Luas=panjang×lebar, jadi 48=panjang×6, memberikan panjang=48÷6=8 cm.",hint:"Bagi total luas dengan lebar yang diketahui untuk menemukan panjang yang hilang."},
{"n":47,"type":"order","micro":"Mengurutkan (menemukan luas bentuk gabungan)","q":"Urutkan langkah-langkah berikut untuk menemukan total luas gambar berbentuk L yang terbuat dari dua persegi panjang.",items:["Jumlahkan kedua luas persegi panjang bersama untuk total luas gabungan","Pecah bentuk L itu menjadi dua persegi panjang terpisah dan sederhana","Hitung luas setiap persegi panjang individual (panjang×lebar)"],answer:[1,2,0],explain:"Pertama pecah bentuknya menjadi persegi panjang sederhana, lalu temukan luas setiap persegi panjang, lalu jumlahkan luas-luas itu bersama.",hint:"Bisakah kamu menghitung luas persegi panjang individual sebelum kamu memecah bentuk gabungan itu menjadi persegi panjang?"},
{"n":48,"type":"mcq","micro":"Luas gabungan (bentuk L)","q":"Sebuah gambar berbentuk L terbuat dari persegi panjang 6 cm × 4 cm dan persegi panjang terpisah 3 cm × 2 cm (tanpa tumpang tindih). Berapa total luasnya?",options:["24 cm persegi","6 cm persegi","30 cm persegi"],answer:2,explain:"6×4=24, dan 3×2=6; total luas=24+6=30 cm persegi.",hint:"Temukan luas masing-masing dari kedua persegi panjang sederhana itu, lalu jumlahkan."},
{"n":49,"type":"mcq","micro":"Keliling gabungan (bentuk L)","q":"Batas luar penuh sebuah gambar berbentuk L terdiri dari 6 segmen lurus berukuran 6 cm, 4 cm, 3 cm, 2 cm, 3 cm, dan 2 cm. Berapa total kelilingnya?",options:["30 cm","24 cm","20 cm"],answer:2,explain:"6+4+3+2+3+2=20 cm, menjumlahkan setiap segmen batas luar.",hint:"Jumlahkan setiap segmen tepi luar tunggal, mengelilingi sepenuhnya bentuk L itu."},
{"n":50,"type":"classify","micro":"Rumus persegi panjang memberikan luas, atau keliling?","q":"Kelompokkan setiap perhitungan berdasarkan apakah dengan benar menemukan LUAS persegi panjang atau KELILINGNYA.",items:["panjang × lebar","2 × (panjang + lebar)","9 cm × 4 cm = 36 cm persegi","2 × (9 cm + 4 cm) = 26 cm"],groups:["Luas","Keliling"],answer:{"Luas":["panjang × lebar","9 cm × 4 cm = 36 cm persegi"],"Keliling":["2 × (panjang + lebar)","2 × (9 cm + 4 cm) = 26 cm"]},explain:"Mengalikan panjang dengan lebar memberikan luas; menjumlahkan panjang dan lebar lalu menggandakannya memberikan keliling.",hint:"Apakah perhitungan itu mengalikan kedua dimensi bersama (luas), atau menjumlahkannya dan menggandakannya (keliling)?"},
{"n":51,"type":"mcq","micro":"Konversi satuan (luas, cm ke m)","q":"Sebuah petak taman persegi panjang berukuran 300 cm kali 200 cm. Berapa luasnya dalam meter PERSEGI (mengetahui 100 cm = 1 m)?",options:["6 meter persegi","500 meter persegi","60.000 meter persegi"],answer:0,explain:"Konversikan dulu: 300 cm=3 m, 200 cm=2 m; luas=3×2=6 meter persegi.",hint:"Konversikan kedua panjang sisi dari sentimeter ke meter DULU, lalu kalikan."},
{"n":52,"type":"mcq","micro":"Konversi satuan (keliling, cm ke m)","q":"Menggunakan petak taman yang sama (300 cm kali 200 cm), berapa kelilingnya dalam METER?",options:["1.000 meter","10 meter","5 meter"],answer:1,explain:"Konversikan dulu: 3 m dan 2 m; keliling=2×(3+2)=2×5=10 meter.",hint:"Konversikan kedua panjang sisi ke meter dulu, lalu terapkan rumus kelilingnya."},
{"n":53,"type":"mcq","micro":"Soal cerita (luas, lantai nyata)","q":"Lantai dapur persegi panjang panjangnya 5 m dan lebarnya 4 m. Jika lantai berbiaya Rp150.000 per meter persegi, berapa total biaya lantainya?",options:["Rp2.700.000","Rp1.350.000","Rp3.000.000"],answer:2,explain:"Luas=5×4=20 meter persegi; biaya=20×150.000=Rp3.000.000.",hint:"Cari dulu total luasnya, lalu kalikan dengan harga per meter persegi."},
{"n":54,"type":"mcq","micro":"Soal cerita (keliling, pagar nyata)","q":"Sebuah halaman persegi panjang panjangnya 12 m dan lebarnya 8 m. Jika pagar berbiaya Rp80.000 per meter, berapa total biaya pagar untuk seluruh kelilingnya?",options:["Rp960.000","Rp3.200.000","Rp7.680.000"],answer:1,explain:"Keliling=2×(12+8)=40 meter; biaya=40×80.000=Rp3.200.000.",hint:"Cari dulu total kelilingnya, lalu kalikan dengan harga per meter."},
{"n":55,"type":"mcq","micro":"Membandingkan hasil luas dan keliling","q":"Mana yang lebih besar: luas persegi 6 cm × 6 cm, atau keliling persegi yang sama (sebagai angka biasa, mengabaikan satuan)?",options:["Luas (36) lebih besar dari keliling (24)","Keliling (24) lebih besar dari luas (36)","Keduanya persis sama"],answer:0,explain:"Luas=6×6=36; keliling=4×6=24. 36 lebih besar dari 24 (meskipun membandingkannya sebagai angka biasa mengabaikan bahwa mereka sebenarnya jenis satuan yang berbeda).",hint:"Hitung kedua nilai secara tepat, lalu bandingkan sebagai angka."},
{"n":56,"type":"tf","micro":"Memeriksa perhitungan luas dengan estimasi","q":"Benar atau Salah: Jika kamu menghitung luas persegi panjang 5 cm kali 8 cm dan mendapat 400 cm persegi, kemungkinan ada yang salah.",answer:true,explain:"5×8 seharusnya 40, bukan 400 — jawaban sebenarnya (40 cm persegi) sepuluh kali lebih kecil, menyarankan kesalahan perkalian (kemungkinan nol yang salah tempat).",hint:"Apakah 400 terlihat seperti perkiraan yang masuk akal untuk 5 dikalikan 8?"},
{"n":57,"type":"mcq","micro":"Soal cerita (sisi hilang dari keliling, pemeriksaan persegi)","q":"Sebuah taman persegi memiliki keliling 36 m. Berapa panjang setiap sisinya?",options:["144 m","9 m","18 m"],answer:1,explain:"Keliling persegi=4×sisi, jadi 36=4×sisi, memberikan sisi=36÷4=9 m.",hint:"Bagi total keliling dengan 4, karena persegi memiliki 4 sisi sama."},
{"n":58,"type":"mcq","micro":"Hubungan fakta (keliling persegi vs luasnya)","q":"Jika sebuah persegi memiliki panjang sisi 10 cm, apakah kelilingnya (dalam cm) lebih besar atau lebih kecil dari luasnya (dalam cm persegi)?",options:["Keliling (40) lebih kecil dari luas (100)","Keliling (40) lebih besar dari luas (100)","Keduanya persis sama"],answer:0,explain:"Keliling=4×10=40; luas=10×10=100. Sebagai angka biasa, 40 lebih kecil dari 100 (sekali lagi, ingat bahwa ini mengukur hal yang benar-benar berbeda dengan satuan berbeda).",hint:"Hitung kedua nilai secara tepat, lalu bandingkan sebagai angka."},
{"n":59,"type":"mcq","micro":"Membandingkan luas gabungan","q":"Bentuk gabungan mana yang total luasnya lebih besar: yang terbuat dari persegi panjang 4×5 plus persegi panjang 2×3, atau yang terbuat dari persegi panjang 3×6 plus persegi panjang 1×4?",options:["Bentuk kedua (3×6 + 1×4 = 22)","Keduanya sama","Bentuk pertama (4×5 + 2×3 = 26)"],answer:2,explain:"Pertama: 4×5=20, 2×3=6, total=26. Kedua: 3×6=18, 1×4=4, total=22. Bentuk pertama memiliki total luas lebih besar.",hint:"Hitung total luas setiap bentuk gabungan dengan menjumlahkan kedua luas persegi panjangnya, lalu bandingkan."},
{"n":60,"type":"mcq","micro":"Memilih rumus yang tepat","q":"Sebuah soal mengatakan: 'Sebuah dek kolam persegi panjang butuh strip anti-selip dipasang sepenuhnya mengelilingi tepi luarnya. Berapa banyak bahan strip yang dibutuhkan?' Rumus mana yang berlaku?",options:["Luas (panjang×lebar), karena strip itu menutupi seluruh permukaan","Keliling (2×(panjang+lebar)), karena strip itu mengelilingi tepi luar","Tidak ada rumus yang berlaku untuk situasi ini"],answer:1,explain:"Strip yang dipasang 'sepenuhnya mengelilingi tepi luar' adalah situasi keliling, bukan situasi luas.",hint:"Apakah strip 'mengelilingi tepi luar' menggambarkan mengelilingi batas, atau menutupi seluruh permukaan?"},

// PHASE D — REASONING (61-80): mengapa keliling dan luas penting secara berbeda, analisis kesalahan, trade-off dunia nyata, klaim luas/keliling yang menyesatkan
{"n":61,"type":"mcq","micro":"Mengapa keliling dan luas melayani tujuan dunia nyata yang berbeda","q":"Mengapa penting bagi pekerja konstruksi untuk dengan jelas mengetahui apakah suatu tugas membutuhkan perhitungan KELILING atau perhitungan LUAS sebelum memesan bahan?",options:["Karena keliling dan luas selalu memberikan hasil angka yang persis sama, jadi sebenarnya tidak masalah","Karena pekerja konstruksi tidak pernah perlu menghitung salah satu dari pengukuran itu","Karena menggunakan pengukuran yang salah (seperti memesan cukup bahan untuk luas padahal hanya keliling yang dibutuhkan, atau sebaliknya) bisa menghasilkan kelebihan besar atau kekurangan serius bahan"],answer:2,explain:"Membingungkan keliling dan luas saat memesan bahan (seperti pagar vs rumput gulung, atau trim vs lantai) bisa menyebabkan pemesanan berlebih atau kurang yang signifikan, memboroskan uang atau menyebabkan keterlambatan proyek.",hint:"Bisakah memesan 'jumlah luas' bahan padahal sebenarnya kamu hanya butuh 'jumlah keliling' (atau sebaliknya) menyebabkan ketidakcocokan serius?"},
{"n":62,"type":"open","micro":"Analisis kesalahan","q":"Seorang siswa menghitung luas persegi panjang (panjang 7 cm, lebar 3 cm) dengan menjumlahkan 7+3+7+3=20 dan melaporkan 20 cm persegi sebagai luasnya. Temukan kesalahannya dan jelaskan metode yang benar.",sample:"Siswa itu menghitung rumus KELILING (menjumlahkan keempat sisi) tetapi melabeli hasilnya sebagai luas — perhitungan luas yang benar adalah panjang×lebar=7×3=21 cm persegi, karena luas membutuhkan mengalikan kedua dimensi bersama, bukan menjumlahkan keempat sisinya.",explain:"Membingungkan rumus keliling berbasis penjumlahan dengan rumus luas berbasis perkalian adalah salah satu kesalahan keliling/luas yang paling umum.",hint:"Apakah menemukan LUAS membutuhkan menjumlahkan keempat sisi, atau mengalikan kedua dimensi berbeda bersama?"},
{"n":63,"type":"open","micro":"Estimasi vs penalaran tepat","q":"Kapan perkiraan luas/keliling cepat (seperti membulatkan pengukuran ke meter terdekat) sudah cukup baik, dan kapan kamu membutuhkan pengukuran yang tepat? Berikan satu contoh nyata masing-masing.",sample:"Perkiraan cepat sudah cukup untuk hal seperti kira-kira menebak berapa banyak biji rumput ekstra yang harus dibeli untuk halaman rumah (membeli sedikit ekstra menutupi kesalahan kecil); pengukuran tepat penting untuk hal seperti memesan kaca potongan khusus untuk jendela, di mana bahkan kesalahan kecil dalam perhitungan luas bisa berarti kacanya sama sekali tidak pas.",explain:"Mengenali kapan presisi keliling/luas benar-benar penting versus kapan perkiraan yang masuk akal sudah cukup mencerminkan penalaran pengukuran yang matang.",hint:"Pikirkan situasi di mana kesalahan estimasi luas/keliling kecil tidak terlalu masalah, dibandingkan dengan situasi di mana itu benar-benar masalah."},
{"n":64,"type":"mcq","micro":"Penalaran tentang klaim luas yang menyesatkan","q":"Sebuah iklan real estat berkata 'ruang tinggal 200 meter persegi yang luas!' tetapi ruangan sebenarnya adalah ruang berbentuk lorong yang panjang dan sangat sempit, hanya lebar 2 meter dan panjang 100 meter. Mengapa angka luas saja mungkin menyesatkan di sini?",options:["Karena total luas yang sama bisa menggambarkan ruang dengan BENTUK dan KEGUNAAN yang sangat berbeda — irisan 2m×100m jauh lebih tidak praktis digunakan daripada ruangan persegi 14m×14m, meskipun keduanya memiliki luas yang mirip atau identik","Karena 200 meter persegi secara matematis tidak mungkin untuk ruangan apa pun","Karena angka luas selalu sepenuhnya akurat dan tidak pernah menyesatkan"],answer:0,explain:"Total luas yang sama bisa disusun dalam bentuk yang sangat berbeda dengan kegunaan dunia nyata yang sangat berbeda, jadi luas saja tidak menjamin suatu ruang benar-benar praktis atau nyaman.",hint:"Bisakah dua ruangan memiliki total luas yang persis sama tetapi berbentuk sangat berbeda dan kegunaannya berbeda dalam kehidupan nyata?"},
{"n":65,"type":"open","micro":"Penalaran dunia nyata","q":"Mengapa seorang petani dengan panjang pagar tetap (keliling tetap) mungkin ingin tahu bentuk persegi panjang mana yang memberikan luas TERBESAR untuk dilingkupi?",sample:"Karena petani itu memiliki total jumlah pagar tetap (keliling tetap) tetapi ingin memaksimalkan ruang pertanian yang dilingkupi dan bisa digunakan (luas), memilih bentuk yang lebih mendekati persegi (alih-alih persegi panjang yang panjang dan tipis) sebenarnya melingkupi lebih banyak luas untuk jumlah pagar yang sama — ini adalah penerapan dunia nyata yang benar-benar berguna dari fakta bahwa bentuk dengan keliling sama bisa memiliki luas berbeda.",explain:"Ini mencerminkan masalah optimasi dunia nyata yang genuine, menerapkan hubungan keliling-vs-luas pada keputusan pertanian yang praktis.",hint:"Dengan total panjang pagar yang sama, apakah persegi panjang yang lebih berbentuk persegi atau persegi panjang yang panjang dan tipis melingkupi lebih banyak ruang?"},
{"n":66,"type":"mcq","micro":"Memilih strategi yang efisien","q":"Untuk menemukan luas ladang persegi panjang besar berukuran 250 m kali 4 m, strategi mana yang paling cepat?",options:["Tidak ada cara efisien untuk menghitung luas ini","Secara fisik menghitung setiap meter persegi satu per satu","Kalikan 250×4 secara langsung (atau pecah menjadi 250×4=250×2×2=500×2=1000), alih-alih mencoba menghitung persegi satuan individual"],answer:2,explain:"Menggunakan rumus perkalian (atau memecah perkaliannya menjadi langkah yang lebih mudah) jauh lebih efisien daripada menghitung persegi satuan untuk luas yang besar.",hint:"Untuk luas yang besar, apakah langsung mengalikan kedua dimensi lebih cepat daripada menghitung setiap persegi satuan individual?"},
{"n":67,"type":"open","micro":"Menyelidiki perbedaan hasil","q":"Dua orang menghitung keliling persegi panjang (panjang 15 m, lebar 9 m) dan mendapat 48 m dan 24 m. Jelaskan rencana langkah demi langkah untuk menemukan jawaban yang benar.",sample:"Hitung ulang dengan hati-hati menggunakan rumusnya: keliling=2×(panjang+lebar)=2×(15+9)=2×24=48 m — memeriksa ini mengonfirmasi 48 m benar, dan jawaban lainnya (24 m) kemungkinan berasal dari lupa menggandakan jumlah panjang dan lebar (24 hanyalah 15+9, tanpa langkah ×2 terakhir).",explain:"Dengan hati-hati menerapkan kembali rumus lengkap langkah demi langkah adalah cara andal menangkap kesalahan keliling umum 'lupa menggandakan.'",hint:"Apakah salah satu dari kedua jawaban mungkin lupa langkah 'kalikan dengan 2' terakhir dalam rumus keliling?"},
{"n":68,"type":"mcq","micro":"Ketika mental math mungkin gagal","q":"Untuk menemukan luas bentuk gabungan tidak beraturan dengan 5 atau 6 bagian persegi panjang berbeda, mengapa metode tertulis atau terhitung mungkin lebih aman daripada mental math murni?",options:["Karena melacak beberapa dimensi persegi panjang berbeda dan perhitungan luas parsial murni di kepala membuatnya mudah kehilangan jejak satu bagian atau membuat kesalahan hitung","Karena mental math tidak pernah berhasil untuk perhitungan luas apa pun","Karena bentuk gabungan sebenarnya tidak bisa diukur sama sekali"],answer:0,explain:"Bentuk gabungan kompleks dengan beberapa bagian sangat rentan kesalahan pelacakan mental, membuat pendekatan tertulis langkah-demi-langkah lebih aman.",hint:"Apakah melacak 5-6 perhitungan persegi panjang terpisah semudah dilakukan murni di kepala seperti satu persegi panjang sederhana tunggal?"},
{"n":69,"type":"open","micro":"Menerapkan penalaran luas/keliling pada keadilan","q":"Dua tetangga berbagi petak taman persegi panjang dan ingin membaginya menjadi dua bagian luas sama menggunakan pagar lurus. Jelaskan bagaimana memahami luas (bukan hanya 'menaksir dengan mata') menjamin pembagian yang benar-benar adil.",sample:"Menghitung total luas dulu (panjang×lebar), lalu mencari tahu tepat di mana garis pembagi perlu diletakkan agar setiap bagian yang dihasilkan memiliki tepat setengah total luas itu, menjamin pembagian 50/50 yang secara matematis adil — sekadar menaksir dengan mata di mana 'setengah' terlihat seharusnya berada bisa dengan mudah menghasilkan satu tetangga mendapat ruang yang bisa digunakan jauh lebih banyak daripada yang lain, terutama jika petak itu bukan bentuk sederhana yang jelas simetris.",explain:"Menghubungkan perhitungan luas yang presisi langsung dengan diskusi keadilan nyata tentang membagi ruang bersama dunia nyata.",hint:"Bisakah sekadar menebak di mana 'titik tengah' terlihat seharusnya berada berisiko memberi satu tetangga luas sebenarnya lebih banyak daripada yang lain?"},
{"n":70,"type":"mcq","micro":"Penalaran tentang rumus luas dan keliling","q":"Mengapa rumus luas (panjang×lebar) menggunakan perkalian, sementara rumus keliling (2×(panjang+lebar)) menggunakan penjumlahan (lalu penggandaan)?",options:["Karena perkalian dan penjumlahan sebenarnya bisa dipertukarkan untuk pengukuran apa pun","Karena luas sebenarnya adalah menghitung berapa persegi satuan yang muat dalam baris DAN kolom (situasi penjumlahan berulang/perkalian), sementara keliling hanyalah menjumlahkan panjang sisi garis lurus individual","Karena pilihan penjumlahan vs perkalian itu sembarang dan tidak ada alasan nyata di baliknya"],answer:1,explain:"Luas melibatkan menggabungkan dua dimensi (baris DAN kolom persegi satuan), secara alami membutuhkan perkalian, sementara keliling hanyalah jumlah tepi lurus individual, secara alami membutuhkan penjumlahan.",hint:"Apakah menemukan berapa persegi satuan yang muat dalam kisi (baris DAN kolom) secara alami melibatkan perkalian, atau penjumlahan sederhana?"},
{"n":71,"type":"open","micro":"Penalaran estimasi kehidupan nyata","q":"Sebelum memesan bahan yang tepat, bagaimana cepat memperkirakan dimensi ruangan ke meter terdekat bisa membantumu merasakan apakah angka luas atau keliling yang dinyatakan (dari denah lantai) terlihat masuk akal?",sample:"Cepat membulatkan dimensi ruangan (seperti memperkirakan sebuah ruangan sebagai kira-kira '5 m kali 4 m') dan mengalikan secara mental (5×4=20) memberikan pemeriksaan kewajaran yang cepat — jika sebuah denah lantai mengklaim ruangan yang sama itu memiliki luas '200 meter persegi,' ketidakcocokan besar dengan perkiraan cepatmu 20-meter-persegi langsung menandakan ada sesuatu yang kemungkinan salah dengan angka yang dinyatakan.",explain:"Ini adalah penggunaan praktis nyata dari estimasi luas untuk pemeriksaan kewajaran cepat pada pengukuran yang dinyatakan yang mungkin salah.",hint:"Akankah perkiraan cepat dan dibulatkan dari dimensi ruangan membantumu menangkap angka luas yang dinyatakan yang jelas tidak masuk akal?"},
{"n":72,"type":"mcq","micro":"Mengenali pola dalam urutan luas","q":"Sebuah urutan persegi memiliki panjang sisi 1, 2, 3, 4, memberikan luas 1, 4, 9, 16. Pola apa yang kamu perhatikan tentang bagaimana luas bertumbuh dibandingkan panjang sisinya?",options:["Luas bertumbuh jauh lebih cepat daripada panjang sisinya sendiri, karena setiap panjang sisi dikalikan dengan dirinya sendiri (dikuadratkan)","Luas sebenarnya menyusut saat panjang sisi bertambah","Luas bertumbuh dengan laju yang persis sama dengan panjang sisinya"],answer:0,explain:"Karena luas adalah sisi×sisi, luas bertumbuh secara tidak proporsional lebih cepat daripada panjang sisinya sendiri (menggandakan panjang sisi sebenarnya melipatempatkan luasnya).",hint:"Apakah menggandakan panjang sisi persegi dari 2 ke 4 menggandakan luasnya, atau meningkatkannya lebih dari dua kali lipat?"},
{"n":73,"type":"open","micro":"Refleksi pilihan strategi","q":"Jelaskan perhitungan keliling/luas nyata di mana kamu akan menggunakan jalan pintas mental math, dan satu di mana kamu ingin menghitung dengan hati-hati dan presisi penuh.",sample:"Untuk hal seperti perkiraan mental kasar berapa banyak tali yang dibutuhkan untuk menandai secara longgar area bermain halaman belakang, jalan pintas mental cepat (membulatkan dimensi) sudah cukup; tetapi untuk hal seperti memesan ubin atau kaca potongan khusus untuk ruang tertentu, perhitungan luas yang hati-hati dan tepat jauh lebih penting, karena kesalahan bisa berarti bahannya tidak pas atau dibutuhkan pemesanan ulang yang mahal.",explain:"Mengenali bahwa strategi jalan pintas bekerja paling baik untuk situasi santai dan bertoleransi, sementara konteks kritis-presisi mendapat manfaat dari perhitungan yang hati-hati dan tepat, menunjukkan penilaian strategis yang nyata.",hint:"Apakah jalan pintas keliling/luas bekerja sama baiknya di setiap situasi, atau hanya ketika kesalahan kecil tidak menyebabkan masalah nyata yang mahal?"},
{"n":74,"type":"mcq","micro":"Menafsirkan pengukuran perkiraan","q":"Sebuah listing real estat mengatakan sebuah ruangan 'kira-kira 20 meter persegi.' Apa yang disarankan 'kira-kira' tentang luas tepatnya?",options:["Luas sebenarnya tidak ada hubungan nyata dengan 20 meter persegi","Luas sebenarnya dijamin persis 20 meter persegi, tanpa variasi sama sekali","Luas sebenarnya kemungkinan dekat dengan 20 meter persegi tetapi mungkin bukan nilai yang tepat itu secara sempurna"],answer:2,explain:"'Kira-kira' menandakan perkiraan — luas sebenarnya diharapkan dekat dengan, tetapi belum tentu sempurna dan tepat, 20 meter persegi.",hint:"Apakah 'kira-kira 20 meter persegi' menjanjikan presisi sempurna, atau hanya kedekatan yang masuk akal?"},
{"n":75,"type":"open","micro":"Perhitungan luas/keliling di bawah tekanan","q":"Saat kompetisi kelas yang cepat di mana siswa harus cepat menghitung luas atau keliling bentuk yang ditunjukkan pada kartu, kebiasaan apa yang membantu menghindari kesalahan ceroboh bahkan saat terburu-buru?",sample:"Cepat bertanya 'apakah aku mencari jarak DI SEKELILING bentuk ini, atau ruang DI DALAMNYA?' sebelum memilih rumus membantu menghindari kesalahan terburu-buru umum yaitu secara tidak sengaja menerapkan rumus luas padahal keliling yang sebenarnya ditanyakan (atau sebaliknya), bahkan saat bekerja di bawah tekanan waktu.",explain:"Kebiasaan spesifik dan cepat 'pengukuran mana yang sebenarnya kucari?' membantu menjaga akurasi bahkan saat bekerja dengan cepat di bawah tekanan.",hint:"Akankah cepat mengonfirmasi apakah soal itu menanyakan tentang TEPI LUAR atau RUANG DI DALAM membantu menghindari kekacauan rumus yang terburu-buru?"},
{"n":76,"type":"mcq","micro":"Kaitan luas, keliling, dan satuan","q":"Mengapa penting bahwa luas dilaporkan dalam satuan 'persegi' (seperti m²) sementara keliling dilaporkan dalam satuan biasa (seperti m)?",options:["Karena satuan sebenarnya tidak membawa arti nyata apa pun tentang apa yang diukur","Karena satuan itu sendiri menandakan JENIS pengukuran apa yang kamu lihat — melihat 'm²' harus langsung memberitahumu itu nilai luas, bukan keliling","Karena 'meter persegi' dan 'meter' sebenarnya bisa dipertukarkan dan berarti hal yang sama"],answer:1,explain:"Satuan itu sendiri ('m²' vs 'm') adalah sinyal bawaan untuk apakah suatu nilai adalah luas atau keliling — mengenali ini membantu menangkap kesalahan pelabelan.",hint:"Jika kamu melihat pengukuran dilaporkan dalam 'm²,' apakah itu saja memberitahumu itu lebih mungkin nilai luas atau keliling?"},
{"n":77,"type":"open","micro":"Menjelaskan luas vs keliling ke orang lain","q":"Seorang siswa yang lebih muda selalu membingungkan luas dan keliling, kadang menggunakan rumus perkalian padahal keliling yang sebenarnya ditanyakan. Apa yang akan kamu ajarkan padanya, dan mengapa itu membantu?",sample:"Saya akan membuat mereka secara fisik menelusuri jari mereka DI SEKELILING tepi luar suatu bentuk sambil berkata 'keliling adalah jarak sekeliling,' dan lalu secara fisik MENUTUPI bagian dalam dengan tangan mereka sambil berkata 'luas adalah ruang di dalam' — menghubungkan setiap kata dengan tindakan fisik membantu membuat perbedaan itu konkret dan mudah diingat, alih-alih hanya dua rumus mirip untuk dibingungkan.",explain:"Mengajarkan perbedaan berbasis-tindakan fisik (menelusuri tepi vs menutupi bagian dalam) mencerminkan pemahaman nyata tentang perbedaan konseptual, bukan hanya menghafal rumus.",hint:"Akankah secara fisik menelusuri tepi versus secara fisik menutupi permukaan membantu membuat perbedaan antara keliling dan luas lebih konkret?"},
{"n":78,"type":"mcq","micro":"Mengenali hasil yang tidak mungkin","q":"Kamu diberitahu bahwa luas yang dihitung sebuah persegi panjang ternyata LEBIH BESAR daripada kelilingnya yang dihitung, untuk persegi panjang dengan sisi hanya 2 cm dan 3 cm. Apakah ini sebenarnya kesalahan?",options:["Tidak, ini TIDAK otomatis kesalahan — untuk persegi panjang kecil, luas (6 cm persegi) memang bisa lebih kecil dari keliling (10 cm), jadi kamu perlu memeriksa angka sebenarnya alih-alih mengasumsikan salah satu selalu lebih besar","Ya, luas dan keliling harus selalu persis sama","Ya, luas harus selalu lebih kecil dari keliling untuk persegi panjang apa pun"],answer:0,explain:"Untuk persegi panjang 2 cm × 3 cm, keliling=10 cm dan luas=6 cm persegi — di sini keliling sebenarnya ANGKA yang lebih besar, menunjukkan tidak ada aturan tetap bahwa salah satunya selalu lebih besar dari yang lain; itu tergantung pada dimensi bentuk sebenarnya.",hint:"Hitung luas dan keliling sebenarnya untuk persegi panjang 2 cm × 3 cm — apakah ada aturan universal untuk mana yang selalu lebih besar secara angka?"},
{"n":79,"type":"open","micro":"Merancang sistem berbasis luas/keliling yang adil","q":"Rancang cara sederhana bagi toko bahan konstruksi untuk membantu pelanggan menghindari memesan JENIS bahan yang salah (seperti memesan lantai alih-alih trim, atau sebaliknya) karena kebingungan antara luas dan keliling.",sample:"Buat formulir pemesanan sederhana yang secara eksplisit bertanya 'Apakah kamu menutupi seluruh permukaan (seperti lantai, cat, atau ubin) atau mengelilingi tepi (seperti trim, pagar, atau tali)?' sebagai pertanyaan pertama, secara otomatis mengarahkan pelanggan ke jenis pengukuran yang benar (luas vs keliling) dan perhitungan sebelum mereka memasukkan angka apa pun, alih-alih mengasumsikan pelanggan sudah tahu pengukuran mana yang dibutuhkan proyek mereka.",explain:"Sistem terpandu yang jelas 'jenis pengukuran apa yang kamu butuhkan?' adalah cara yang benar-benar praktis untuk mencegah kebingungan dunia nyata yang umum dan mahal.",hint:"Akankah secara eksplisit bertanya apakah suatu proyek melibatkan 'menutupi permukaan' atau 'mengelilingi tepi' sebelum perhitungan apa pun membantu mencegah pemesanan jenis bahan yang salah?"},
{"n":80,"type":"mcq","micro":"Pemeriksaan keyakinan luas/keliling","q":"Kamu menghitung luas persegi panjang 6 m × 9 m tiga kali terpisah dan mendapat 54, 54, dan 15. Apa kesimpulan yang paling masuk akal?",options:["Tidak ada dari ketiga percobaan yang bisa dipercaya","Luas sebenarnya pasti 15 meter persegi, karena itu angka yang lebih kecil dan berbeda","Luas sebenarnya sangat mungkin 54 meter persegi, karena cocok dengan dua dari tiga percobaan (dan cocok dengan perhitungan yang benar, 6×9=54)"],answer:2,explain:"Ketika sebagian besar percobaan berulang cocok (dua dari tiga mendapat 54), dan nilai itu cocok dengan perkalian yang benar, itu adalah hasil yang bisa dipercaya (15 kemungkinan adalah penjumlahan tidak sengaja dari 6+9).",hint:"Jawaban mana yang muncul lebih sering di antara ketiga percobaanmu, dan apakah cocok dengan perkalian yang benar (6×9)?"},

// PHASE E — CHALLENGE (81-100): kapstone, masalah luas/keliling nyata multi-langkah, investigasi, refleksi
{"n":81,"type":"open","micro":"Masalah nyata multi-langkah","q":"Sebuah ruangan persegi panjang berukuran 6 m kali 4 m. Kamu ingin memasang trim baseboard mengelilingi seluruh ruangan (kecuali celah pintu selebar 1 m di mana tidak dibutuhkan trim) dan karpet menutupi seluruh lantai. Berapa banyak trim dan karpet yang kamu butuhkan, dan bagaimana kamu menemukan masing-masing?",sample:"Keliling=2×(6+4)=20 m total, dikurangi celah pintu 1 m = 19 m trim yang dibutuhkan. Karpet butuh seluruh luas lantai terlepas dari celah pintu (pintu tidak mengurangi luas lantai): luas=6×4=24 meter persegi karpet — ditemukan dengan menghitung keliling untuk trim (lalu mengurangkan celah pintu), dan luas untuk karpet (celah pintu tidak mempengaruhi luas lantai).",explain:"Penerapan langsung baik keliling (dengan penyesuaian) maupun luas pada dua kebutuhan renovasi rumah nyata yang benar-benar berbeda di ruangan yang sama.",hint:"Trim butuh keliling (dikurangi celah pintu); karpet butuh luas penuh (celah pintu tidak menghilangkan ruang lantai apa pun)."},
{"n":82,"type":"open","micro":"Merancang pemeriksaan anggaran berbasis luas nyata","q":"Kamu ingin mengecat dinding persegi panjang yang lebarnya 5 m dan tingginya 3 m, dengan satu jendela seluas 2 meter persegi yang tidak akan dicat. Jika cat berbiaya Rp45.000 per meter persegi, berapa total biaya pengecatan, dan bagaimana kamu menghitungnya?",sample:"Total luas dinding=5×3=15 meter persegi; kurangkan jendelanya: 15−2=13 meter persegi yang sebenarnya perlu dicat; biaya=13×45.000=Rp585.000 — ditemukan dengan menghitung luas dinding penuh dulu, lalu mengurangkan luas jendela yang tidak dicat, sebelum menerapkan biaya per meter persegi.",explain:"Menerapkan perhitungan luas nyata dengan pengecualian yang dikurangkan langsung pada keputusan penganggaran renovasi rumah yang sungguhan.",hint:"Cari luas dinding penuh dulu, lalu kurangkan luas jendela (karena tidak akan dicat), sebelum menghitung biayanya."},
{"n":83,"type":"open","micro":"Menyelidiki klaim luas yang tidak konsisten","q":"Sebuah listing properti mengklaim sebuah ruangan '25 meter persegi,' tetapi ketika kamu mengukurnya sendiri, kamu mendapat 4,5 m kali 5 m (22,5 meter persegi). Bagaimana kamu akan menyelidiki perbedaan ini dengan jujur?",sample:"Periksa ulang pengukuranmu sendiri dengan hati-hati untuk akurasi (mengukur sepanjang panjang dinding-ke-dinding sebenarnya, bukan diagonal atau dengan pita yang miring), dan pertimbangkan bahwa angka yang tercantum mungkin memasukkan atau mengecualikan area tertentu secara berbeda (seperti lemari built-in, ceruk, atau pembulatan), atau mungkin sekadar mencerminkan pengukuran yang usang atau tidak akurat — alih-alih mengasumsikan salah satu angka otomatis benar, pengukuran ulang yang hati-hati dan pemeriksaan apa persisnya yang termasuk dalam angka listing itu akan membantu menyelesaikan perbedaan itu.",explain:"Mengenali dan dengan jujur menyelidiki perbedaan luas nyata, alih-alih mengasumsikan salah satu angka otomatis salah, mencerminkan penalaran matang tentang klaim luas dalam listing properti nyata.",hint:"Bisakah luas yang tercantum memasukkan atau mengecualikan bagian ruangan (seperti lemari atau ceruk) secara berbeda dari pengukuranmu sendiri yang langsung?"},
{"n":84,"type":"open","micro":"Koneksi sejarah/budaya","q":"Cari tahu (atau ingat kembali) bagaimana perhitungan luas dan keliling secara historis penting dalam bidang seperti pertanian, kepemilikan tanah, atau arsitektur kuno (seperti perpajakan tanah berdasarkan luas ladang, atau dimensi monumen kuno). Jelaskan singkat apa yang kamu temukan.",sample:"Secara historis, menghitung luas tanah secara akurat penting untuk perpajakan yang adil (karena petani sering dikenai pajak berdasarkan berapa banyak tanah — luas — yang mereka miliki atau garap) dan untuk membagi tanah warisan atau yang dibeli secara adil di antara banyak orang, sementara perhitungan keliling penting untuk tugas seperti membangun tembok atau pagar mengelilingi properti — menunjukkan bahwa perhitungan ini memiliki kepentingan praktis yang nyata dan bertaruhan tinggi selama ribuan tahun, bukan hanya topik kelas matematika modern.",explain:"Menghubungkan luas dan keliling dengan kepentingan sejarah nyatanya dalam kepemilikan tanah dan perpajakan menunjukkan relevansi skill ini yang lebih luas di dunia nyata.",hint:"Mengapa menghitung LUAS tanah petani secara akurat (bukan hanya kelilingnya) mungkin sangat penting untuk perpajakan tanah historis yang adil?"},
{"n":85,"type":"open","micro":"Masalah pengukuran nyata multi-langkah","q":"Sebuah kolam renang persegi panjang panjangnya 25 m dan lebarnya 10 m, dikelilingi jalan setapak yang lebarnya 2 m di semua sisi. Berapa luas HANYA jalan setapaknya (tidak termasuk kolamnya sendiri)?",sample:"Persegi panjang luar total (kolam + jalan di semua sisi): panjang=25+2+2=29 m, lebar=10+2+2=14 m, total luas=29×14=406 meter persegi. Luas kolam saja=25×10=250 meter persegi. Luas jalan=406−250=156 meter persegi — ditemukan dengan menghitung total luas kolam-plus-jalan, lalu mengurangkan hanya luas kolam itu sendiri.",explain:"Menerapkan penalaran luas gabungan (pengurangan) pada skenario lansekap/konstruksi nyata yang cukup kompleks.",hint:"Hitung luas seluruh persegi panjang luar (kolam plus jalan di sekelilingnya), lalu kurangkan luas kolam itu sendiri untuk mengisolasi hanya jalan setapaknya."},
{"n":86,"type":"open","micro":"Refleksi kesalahan luas/keliling","q":"Ceritakan saat nyata (dalam skill ini atau dalam kehidupan nyata) ketika kamu membuat kesalahan dengan luas atau keliling — seperti membingungkan kedua rumus, lupa konversi satuan, atau salah menghitung bagian bentuk gabungan. Apa penyebabnya, dan apa yang akan kamu lakukan berbeda sekarang?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti menggunakan rumus keliling padahal luas yang dibutuhkan, lupa mengonversi satuan sebelum menghitung, atau melewatkan satu bagian bentuk gabungan) dan menyebutkan perbaikan konkret, seperti selalu bertanya 'tepi atau ruang di dalam?' dulu, atau memeriksa ulang satuan sebelum menghitung.",explain:"Merenungkan kesalahan luas/keliling pribadi yang nyata, dengan perbaikan konkret, menunjukkan skill ini sudah benar-benar tertanam.",hint:"Ingat kembali momen ketika perhitungan luas atau keliling ternyata salah — apa tepatnya yang salah dalam langkahmu?"},
{"n":87,"type":"open","micro":"Merancang proyek luas/keliling kelas","q":"Rancang proyek kelas sederhana bagi 30 siswa untuk mempraktikkan perhitungan luas dan keliling nyata — seperti mengukur kelas itu sendiri dan menghitung berapa banyak lantai dan trim yang dibutuhkannya.",sample:"Minta siswa bekerja dalam kelompok kecil untuk mengukur panjang dan lebar kelas menggunakan pita ukur, hitung baik luas ruangan (untuk lantai) maupun kelilingnya (untuk trim baseboard), lalu bandingkan hasil kelompok mereka dengan pengukuran kelompok lain dari ruangan yang sama untuk memeriksa konsistensi dan membahas perbedaan pengukuran apa pun yang ditemukan.",explain:"Ini adalah sistem praktis dan langsung untuk andal mempraktikkan perhitungan luas dan keliling nyata menggunakan ruang dunia nyata yang genuine dan bersama.",hint:"Akankah beberapa kelompok mengukur ruangan nyata yang SAMA, lalu membandingkan hasil, membantu siswa menangkap dan memahami ketidakkonsistenan pengukuran?"},
{"n":88,"type":"open","micro":"Memperkirakan dan memverifikasi total luas","q":"Perkirakan total luas denah rumah yang terdiri dari 3 ruangan kira-kira 4×5 m, 3×3 m, dan 6×4 m, lalu jelaskan bagaimana kamu akan memverifikasi perkiraanmu.",sample:"Perkiraan cepat: kira-kira 20+9+24=53 meter persegi total; kamu bisa memverifikasi ini dengan dengan hati-hati mengukur ulang dan menghitung ulang luas tepat setiap ruangan secara individual, lalu menjumlahkannya kembali, memeriksa bahwa total tepatnya cukup dekat dengan perkiraan bulat awal.",explain:"Ini menerapkan teknik 'perkirakan setiap bagian secara kasar, lalu verifikasi dengan perhitungan tepat' pada skenario luas multi-ruangan yang nyata.",hint:"Bisakah memperkirakan luas setiap ruangan secara kasar, lalu menjumlahkan total kasar itu bersama, memberikan perkiraan awal yang masuk akal sebelum perhitungan tepat?"},
{"n":89,"type":"open","micro":"Menyelidiki perbedaan nyata (alat ukur)","q":"Kamu mengukur keliling ruangan persegi panjang yang sama dengan dua alat berbeda — pita ukur dan alat ukur laser — dan mendapat 38,2 m dan 38,5 m. Berikan dua kemungkinan penjelasan berbeda untuk perbedaan 0,3 m ini, dan bagaimana kamu akan menyelidiki masing-masing.",sample:"Kemungkinan 1: pita ukur mungkin sedikit melorot atau tidak dipegang sepenuhnya lurus di sepanjang setiap dinding, menyebabkan sedikit perkiraan berlebih atau kurang — ukur ulang dengan hati-hati, menjaga pitanya kencang dan lurus. Kemungkinan 2: alat laser mungkin mengukur ke titik referensi yang sedikit berbeda (seperti memperhitungkan ketebalan baseboard secara berbeda dari pita ukur yang dipegang menempel dinding) — periksa titik referensi pengukuran spesifik setiap alat dalam instruksinya.",explain:"Mempertimbangkan beberapa penyebab yang mungkin untuk perbedaan alat pengukuran dunia nyata, dan cara mengujinya, mencerminkan penalaran investigatif yang genuine tentang presisi.",hint:"Bisakah perbedaan itu berasal dari bagaimana setiap alat digunakan secara fisik (pita yang melorot) atau dari perbedaan titik referensi tepat yang diukur setiap alat?"},
{"n":90,"type":"open","micro":"Kaitan luas/keliling dan statistik","q":"Sebuah laporan real estat menyatakan 'ukuran rumah rata-rata di lingkungan ini adalah 150 meter persegi.' Mengapa satu angka luas rata-rata ini mungkin tidak memberitahumu banyak tentang rumah TERTENTU mana pun di lingkungan itu?",sample:"Rata-rata menggabungkan banyak ukuran rumah individual berbeda menjadi satu angka ringkasan — beberapa rumah bisa jauh lebih kecil (seperti 80 meter persegi) dan yang lain jauh lebih besar (seperti 250 meter persegi), dengan rata-rata 150 belum tentu cocok dekat dengan rumah individual khas mana pun, menunjukkan mengapa satu luas rata-rata tidak mengungkapkan rentang atau variasi sebenarnya di antara rumah nyata di lingkungan itu.",explain:"Ini menghubungkan pemahaman luas langsung dengan menafsirkan rata-rata statistik nyata dengan benar dan batasannya.",hint:"Apakah mengetahui HANYA ukuran rumah rata-rata memberitahumu rentang ukuran sebenarnya rumah individual di lingkungan itu?"},
{"n":91,"type":"open","micro":"Mini proyek","q":"Rancang dan hitung skenario berbasis luas/keliling nyata (seperti merencanakan taman, memasang lantai ruangan, atau memagari halaman), menunjukkan pekerjaanmu dengan jelas. Laporkan hasil dan metodemu.",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan operasi luas dan/atau keliling nyata (menghitung, menemukan sisi yang hilang, atau bekerja dengan bentuk gabungan) dalam skenario realistis yang kamu rancang sendiri.",explain:"Ini adalah penerapan kapstone langsung dari keterampilan luas dan keliling pada tugas nyata yang kamu rancang sendiri.",hint:"Akankah menunjukkan setiap langkah perhitungan dengan jelas (bukan hanya jawaban akhir) membuat pekerjaanmu lebih mudah diperiksa dan dipercaya orang lain?"},
{"n":92,"type":"open","micro":"Menjelaskan luas vs keliling ke anak yang jauh lebih muda","q":"Bagaimana kamu akan menjelaskan perbedaan antara luas dan keliling kepada anak yang belum pernah melihat kedua istilah ini, menggunakan sesuatu yang mereka pahami?",sample:"Saya akan menggunakan halaman belakang nyata — 'keliling itu seperti berjalan sepenuhnya mengelilingi tepi halaman di sepanjang garis pagar, tetapi luas itu seperti berapa banyak rumput yang kamu butuhkan untuk menutupi SELURUH halaman — berjalan mengelilingi tepi (keliling) dan menutupi seluruh ruang (luas) adalah dua pekerjaan yang sama sekali berbeda, meskipun keduanya tentang halaman yang sama.'",explain:"Menyederhanakan konsep-ganda abstrak menggunakan contoh yang konkret dan relevan menunjukkan pemahaman yang mendalam dan bisa dipindahkan.",hint:"Ruang luar sehari-hari apa (seperti halaman belakang) yang akan membantu menjelaskan perbedaan antara 'berjalan mengelilingi tepi' dan 'menutupi seluruh ruang'?"},
{"n":93,"type":"open","micro":"Refleksi","q":"Menurutmu mengapa memulai dengan tindakan fisik nyata (seperti benar-benar berjalan mengelilingi tepi untuk keliling, atau benar-benar menutupi lantai dengan ubin untuk luas) begitu penting sebelum melanjutkan ke rumus abstrak?",sample:"Tanpa dulu merasakan apa yang sebenarnya diwakili keliling dan luas melalui tindakan fisik nyata (berjalan mengelilingi tepi vs menutupi permukaan), rumus abstrak (2×(panjang+lebar) vs panjang×lebar) bisa terasa seperti dua kumpulan angka sembarang yang mudah dibingungkan untuk dihafal alih-alih dua tindakan dunia nyata yang benar-benar berbeda — membangun dari pengalaman fisik konkret dan nyata dulu membantu rumus abstrak benar-benar masuk akal secara konseptual nanti, alih-alih hanya dihafal dan tertukar.",explain:"Ini mencerminkan wawasan nyata tentang mengapa perjalanan Konkret-Piktorial-Abstrak sangat penting khususnya untuk luas dan keliling, skill yang sering membingungkan justru karena diajarkan secara abstrak terlalu awal.",hint:"Akankah kedua rumus itu lebih masuk akal (dan lebih kecil kemungkinannya tertukar) bagi seseorang yang telah secara fisik mengalami 'berjalan mengelilingi tepi' versus 'menutupi permukaan,' atau bagi seseorang yang hanya menghafal rumusnya?"},
{"n":94,"type":"open","micro":"Keputusan bisnis menggunakan luas/keliling","q":"Sebuah perusahaan lansekap menemukan bahwa halaman klien memiliki keliling tetap untuk pemagaran tetapi ingin memaksimalkan luas rumput yang dilingkupi untuk ruang bermain. Keputusan bisnis/desain apa yang mungkin didukung hubungan luas-vs-keliling ini, dan apa yang masih perlu diwaspadai perusahaan itu?",sample:"Mereka mungkin merekomendasikan merancang area yang dilingkupi sedekat mungkin dengan bentuk persegi (alih-alih persegi panjang yang panjang dan tipis), karena lingkupan yang lebih berbentuk persegi memaksimalkan luas yang bisa digunakan untuk jumlah pagar tertentu — tetapi tetap harus waspada terhadap batasan praktis, seperti bentuk sebenarnya halaman itu, struktur yang sudah ada, atau kebutuhan ruang spesifik klien, yang mungkin membuat desain persegi sempurna tidak praktis meskipun secara matematis optimal.",explain:"Menerapkan hubungan optimasi keliling-vs-luas pada keputusan desain lansekap nyata, sambil menandai batasan solusi 'optimal' yang murni matematis.",hint:"Apakah bentuk persegi sempurna yang secara matematis optimal untuk luas (dengan keliling tetap) menjamin itu juga pilihan PALING PRAKTIS untuk setiap halaman nyata?"},
{"n":95,"type":"open","micro":"Luas bertemu keadilan (membagi tanah)","q":"Dua saudara kandung mewarisi sebidang tanah persegi panjang dan ingin membaginya menjadi dua bagian persegi panjang berluas sama dengan satu pagar pembagi lurus. Jelaskan bagaimana memahami luas (bukan hanya menaksir dengan mata) menjamin setiap saudara mendapat bagian yang benar-benar adil dan sama.",sample:"Hitung total luas tanah dulu (panjang×lebar), lalu tentukan tepat di mana garis pembagi lurus perlu diletakkan (baik membagi panjangnya atau lebarnya menjadi dua) sehingga setiap bagian persegi panjang yang dihasilkan memiliki tepat setengah total luasnya — menggunakan perhitungan yang presisi alih-alih menebak secara visual menjamin tidak ada saudara yang berakhir dengan tanah yang bisa digunakan lebih banyak atau lebih sedikit secara nyata daripada yang lain.",explain:"Menghubungkan perhitungan luas yang presisi langsung dengan diskusi keadilan nyata tentang membagi properti warisan bersama dunia nyata.",hint:"Akankah menebak secara visual di mana 'setengah tanah' terlihat seharusnya berisiko memberi satu saudara luas sebenarnya lebih banyak daripada yang lain?"},
{"n":96,"type":"open","micro":"Batasan statistik luas/keliling","q":"Sebuah laporan menyatakan 'taman ini memiliki 50.000 meter persegi ruang hijau.' Apa yang bisa diberitahukan angka luas ini, dan apa yang tidak bisa diberitahukannya sendiri?",sample:"Ini bisa memberitahumu gambaran umum seberapa besar ruang hijau taman itu secara keseluruhan — tetapi tidak bisa memberitahumu bagaimana ruang itu sebenarnya berbentuk atau terdistribusi (bisa jadi satu ladang terbuka yang sangat besar, atau banyak petak hijau kecil yang tersebar dan terputus-putus dipisahkan oleh area beraspal), atau apakah itu benar-benar bisa diakses dan digunakan, jadi angka luas tunggal itu tidak menangkap tata letak atau kegunaan sebenarnya ruang itu.",explain:"Mengenali bahwa statistik luas memberikan angka ringkasan yang berguna, tetapi tidak otomatis gambaran penuh bentuk, tata letak, atau kegunaan sebenarnya suatu ruang, adalah koneksi berpikir kritis yang penting.",hint:"Apakah mengetahui HANYA total luas ruang hijau memberitahumu apakah itu disusun sebagai satu ladang besar yang terhubung, atau banyak petak kecil yang tersebar?"},
{"n":97,"type":"open","micro":"Investigasi nyata multi-langkah","q":"Rancang rencana untuk mengetahui, menggunakan luas dan keliling, kira-kira berapa banyak bahan (cat untuk dinding, lantai, dan trim) yang dibutuhkan proyek renovasi rumah kecil, tanpa mengukur setiap sudut kecil dengan presisi ekstrem.",sample:"Ukur panjang dan lebar utama setiap ruangan sampai setengah-meter terdekat yang wajar (alih-alih melacak setiap ceruk kecil atau sudut tidak beraturan dengan presisi ekstrem), hitung luas setiap ruangan (untuk lantai/cat) dan kelilingnya (untuk trim) menggunakan pengukuran wajar itu, lalu tambahkan penyangga praktis kecil (seperti ekstra 5-10%) untuk memperhitungkan limbah pemotongan, ketidakteraturan kecil, atau ceruk kecil yang terlewat, alih-alih mencoba menghitung total yang mustahil tepat.",explain:"Menerapkan strategi 'ukur dimensi utama yang wajar, hitung, dan tambahkan penyangga praktis' pada tugas perencanaan renovasi dunia nyata yang benar-benar praktis.",hint:"Akankah mengukur dimensi utama setiap ruangan pada tingkat presisi yang wajar (plus penyangga kecil untuk limbah) tetap memberikan perkiraan bahan yang berguna dan praktis?"},
{"n":98,"type":"open","micro":"Luas/keliling dan teknologi","q":"Banyak aplikasi dan perangkat (seperti aplikasi real estat, perangkat lunak desain denah lantai, atau alat ukur laser) secara otomatis menghitung luas dan keliling dari sebuah foto atau beberapa ketukan. Apa satu keuntungan dan satu risiko dari sepenuhnya mempercayai perhitungan otomatis semacam ini?",sample:"Keuntungan: alat-alat ini bisa secara instan dan akurat menghitung luas dan keliling untuk ruang yang kompleks atau tidak beraturan jauh lebih cepat daripada pengukuran dan perhitungan manual. Risiko: mempercayai buta angka yang dihasilkan otomatis tanpa memahami apa persisnya yang diukur (seperti apakah aplikasi denah lantai memasukkan atau mengecualikan lemari, atau mengukur ke bagian dalam vs luar dinding) bisa menyebabkan ketidakcocokan antara angka aplikasi itu dan apa yang sebenarnya kamu butuhkan untuk tugas dunia nyata tertentu.",explain:"Memperluas penalaran luas/keliling ke alat digital nyata, menimbang kenyamanan perhitungan otomatis melawan risiko tidak memahami apa persisnya yang diukur.",hint:"Apakah angka luas atau keliling yang dihasilkan otomatis selalu menentukan apa persisnya yang termasuk atau dikecualikan dalam pengukurannya?"},
{"n":99,"type":"open","micro":"Menyelidiki angka luas yang bertentangan","q":"Dua sumber berbeda memberikan angka total luas yang sedikit berbeda untuk taman nasional yang sama (seperti 5.200 kilometer persegi versus 5.450 kilometer persegi). Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan seperti ini?",sample:"Pembaca yang cermat sebaiknya menyadari bahwa mengukur sesuatu yang besar dan berbentuk tidak beraturan seperti batas taman nasional bisa benar-benar berbeda berdasarkan tepat di mana batas resminya digambar, metode pengukuran atau pemetaan yang digunakan, atau apakah area tertentu (seperti zona penyangga yang berdekatan) termasuk, alih-alih mengasumsikan satu sumber sekadar membuat kesalahan, dan sebaiknya melihat bagaimana setiap sumber mendefinisikan batas taman itu sebelum memutuskan angka mana yang dipercaya untuk tujuan tertentu.",explain:"Menerapkan penalaran yang matang, skeptis namun adil, pada statistik luas yang tampak bertentangan, menghindari kepercayaan buta maupun tuduhan yang tidak adil.",hint:"Bisakah dua sumber benar-benar tidak sepakat tentang luas taman karena definisi batas atau metode pengukuran berbeda, bukan karena salah satu membuat kesalahan?"},
{"n":100,"type":"open","micro":"Refleksi kapstone","q":"Melihat kembali skill Luas & Keliling ini — mulai dari tindakan fisik nyata seperti berjalan mengelilingi tepi dan menutupi lantai dengan ubin, ke gambar kisi dan diagram berlabel, dan akhirnya ke rumus abstrak dan penalaran tentang trade-off dunia nyata — kebiasaan apa yang sekarang kamu miliki saat melihat atau mengerjakan luas atau keliling?",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis bertanya 'apakah aku mengukur tepi atau ruang di dalam?' sebelum memilih rumus, memeriksa ulang bahwa satuannya masuk akal (satuan biasa untuk keliling, satuan persegi untuk luas), atau lebih berhati-hati dengan bentuk gabungan dengan memecahnya menjadi persegi panjang sederhana dulu.",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa skill ini sudah tertanam.",hint:"Pikirkan momen dalam unit ini ketika luas dan keliling berhenti menjadi rumus yang mudah dibingungkan dan mulai masuk akal sebagai dua pengukuran dunia nyata yang benar-benar berbeda."},
];
